def control(obs):
    g = globals()
    t = obs.get('t', 0.0)
    if 'ph' not in g:
        g['ph'] = 'fwd'
        g['t0'] = t
    h = obs.get('hitch_deg', 0.0)
    rr = obs.get('rig', {}).get('trailer_rear', [0.0, 0.0])
    ry = rr[1]
    v = obs.get('motion', {}).get('v_mps', 0.0)
    if g['ph'] == 'fwd':
        if h < 0.3 or t - g['t0'] > 5.0:
            g['ph'] = 'stop'
        else:
            return (0.0, 0.4, 180)
    if g['ph'] == 'stop':
        if abs(v) < 0.05:
            g['ph'] = 'rev'
        else:
            return (0.0, 0.0, 180)
    steer = 2.0 * h + 8.0 * ry
    if steer > 20:
        steer = 20.0
    if steer < -20:
        steer = -20.0
    return (steer, -0.5, 180)

