YT = -0.4
phase = 'fwd'
t0 = None

def control(obs):
    global phase, t0
    t = obs.get('t', 0.0)
    if t0 is None:
        t0 = t
    h = obs.get('hitch_deg', 0.0)
    y = obs['rig']['trailer_rear'][1]
    if phase == 'fwd':
        # pull forward gently with a small right steer to move the rear off the left rail
        if y < -0.3 or t - t0 > 4.0:
            phase = 'rev'
        else:
            return (-6.0, 0.8, 0)
    hd = 4.0 * (YT - y)
    hd = max(-20.0, min(20.0, hd))
    steer = 2.0 * (h - hd)
    steer = max(-40.0, min(40.0, steer))
    return (steer, -0.7, 170)

